use ferriboot_build::{check_platform_chip, emit_public_keys, write_out};
use rp2350_layout as layout;

fn main() {
    check_platform_chip("ferriboot-rp", layout::CHIP);
    emit_public_keys("../../../keys/dev-p256.pub.pem");

    // The complete linker script: MEMORY from the layout crate, then bootloader.x.
    let memory = format!(
        "/* @generated by boards/rp2350/ferriboot/build.rs from rp2350-layout. */
MEMORY
{{
    FLASH     : ORIGIN = {:#010x}, LENGTH = {:#x}
    RAM       : ORIGIN = {:#010x}, LENGTH = {:#x}
    BOOT_INFO : ORIGIN = {:#010x}, LENGTH = {:#x}
}}

",
        layout::XIP_BASE,
        layout::BOOTLOADER_SIZE,
        layout::RAM_BASE,
        layout::BOOT_INFO_ADDRESS - layout::RAM_BASE,
        layout::BOOT_INFO_ADDRESS,
        layout::BOOT_INFO_SIZE,
    );
    let script = write_out("bootloader.x", memory + include_str!("ld/bootloader.x"));
    println!("cargo:rustc-link-arg=-T{}", script.display());
    println!("cargo:rerun-if-changed=ld/bootloader.x");
}
